select '1. backup table exists' as check, case when exists ( select 1 from information_schema.tables where table_schema = 'public' and table_name = 'planners_backup_0034' ) then 'OK' else 'PROBLEM - 0034 did not run' end as result; select '2. backup covers every plan' as check, case when (select count(*) from public.planners_backup_0034) >= (select count(*) from public.planners) then 'OK' else 'PROBLEM - fewer backed up than exist' end as result, (select count(*) from public.planners) as plans_now, (select count(*) from public.planners_backup_0034) as plans_backed_up; select '3. untouched examples cleared' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' plan(s) are still the seeded example' end as result from public.planners where content->'thesis'->>'quote' like '%trending audio%' and content->'overview'->>'heading' = 'Three jobs, one feed' and content->'pillars'->'items'->0->>'name' = 'Client Work' and content->'guarantee'->>'body' like '%inbound DMs%'; select '4. sections on blanked plans' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' blanked plan(s) missing a section' end as result from public.planners where coalesce(content->'thesis'->>'quote', '') = '' and coalesce(content->'overview'->>'desc', '') = '' and not (content ?& array[ 'hero','thesis','overview','branding','pillars','format', 'workflow','metrics','competitors','producing','slots','timeline','guarantee' ]); select '5. headings on blanked plans' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' blanked plan(s) lost their headings' end as result from public.planners where coalesce(content->'thesis'->>'quote', '') = '' and coalesce(content->'overview'->>'desc', '') = '' and (coalesce(content->'branding'->>'heading', '') = '' or coalesce(content->'pillars'->>'heading', '') = '' or coalesce(content->'slots'->>'desc', '') = ''); select '6. branding rows on blanked plans' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' blanked plan(s) have the wrong rows' end as result from public.planners where coalesce(content->'thesis'->>'quote', '') = '' and jsonb_array_length(content->'branding'->'rows') <> 9; select '7. plans with writing in them' as check, 'kept ' || count(*) || ' (these were left untouched)' as result from public.planners where coalesce(content->'thesis'->>'quote', '') <> '' or coalesce(content->'overview'->>'desc', '') <> '' or coalesce(content->'guarantee'->>'body', '') <> ''; select c.name as client, p.status, case when coalesce(p.content->'thesis'->>'quote', '') <> '' or coalesce(p.content->'overview'->>'desc', '') <> '' then 'kept - has writing in it' else 'blank template' end as outcome, left(coalesce(p.content->'hero'->>'brand', ''), 40) as headline from public.planners p join public.clients c on c.id = p.client_id order by outcome, c.name;
